"""Publish the one-piece crystal head correction and unchanged-body evidence."""
from pathlib import Path
import json,hashlib,shutil,re,subprocess
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'docs/art/creature-models/2026-10-14/rift-titan-cracked-head-r12';OLD=OUT.parent/'rift-titan-notched-r11'
row=json.loads((OUT/'refinement-metrics.json').read_text());ID=row['id'];previous='underworld-boss-rift-titan-notched-r11'
checks={n:json.loads((OUT/(n+'.json')).read_text()) for n in ('verification','attachment-verification','closing-face-verification','crystal-face-verification','thorax-face-verification','neck-head-face-verification','side-orientation','head-verification','body-preservation')}
assert row['triangles']==checks['verification']['triangles']==1792<row['soft_cap']==1800
assert checks['attachment-verification']['result']=='PASS' and checks['attachment-verification']['endpoints']==76
for n,total in [('closing-face-verification',8064),('crystal-face-verification',14112),('thorax-face-verification',2016),('neck-head-face-verification',1512)]:assert checks[n]['result']=='PASS' and checks[n]['sampled_points']==total and checks[n]['poses']==36 and checks[n]['max_outside_distance_metres']==0
head=checks['head-verification'];assert head['result']=='PASS' and head['connected_components']==1 and head['closed'] and head['triangles']==108 and head['surface_role_triangles']=={'1':76,'2':24,'3':8}
body=checks['body-preservation'];assert body['result']=='PASS' and body['max_coordinate_difference_metres']==0
sha=hashlib.sha256((ROOT/row['source']).read_bytes()).hexdigest();assert checks['verification']['source_sha256']==checks['side-orientation']['source_sha256']==sha and checks['side-orientation']['camera_direction'][0]<0
detail=json.loads((OUT/'before/detail-provenance.json').read_text());assert detail['source_sha256']==hashlib.sha256((ROOT/detail['source']).read_bytes()).hexdigest()
views=('three-quarter','front','side','front-clay','side-clay','side-reference')
for view in views:shutil.copy2(OLD/(previous+'--'+view+'.png'),OUT/'before'/(previous+'--'+view+'.png'))
for p in ('concept-front.png','concept-side.png'):shutil.copy2(OLD/p,OUT/p)
html=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rift Titan — one crystal with a recessed crack r12</title>
<style>body{{background:#14191c;color:#e4e5df;font:16px system-ui;max-width:1500px;margin:auto;padding:24px}}p{{line-height:1.6;max-width:1150px}}a{{color:#9ccdda}}img{{width:100%;object-fit:contain;background:#171e22}}.pair{{display:grid;grid-template-columns:1fr 1fr;gap:14px}}.reference img{{height:650px}}figure{{margin:0}}figcaption{{padding:8px;color:#bbc5c6}}button{{background:#283840;color:#e4e5df;border:1px solid #60747a;padding:8px 14px;margin:5px;cursor:pointer}}@media(max-width:800px){{.pair{{grid-template-columns:1fr}}.reference img{{height:500px}}}}</style>
<h1>Rift Titan — one crystal with a recessed crack r12</h1>
<p><strong>Corrected interpretation: the head is one crystal form with a recessed, beveled fissure.</strong> The previous separate halves and floating purple slivers are replaced by one connected closed shell. The exposed purple crystal is the deep floor of the crack, sharing geometry with its bevel walls and outer cortex. A continuous rear wall remains behind the fissure; it is not a through-slot or a gap between two independent uprights.</p>
<p>The six neck-rib ends are seated into this new head. Saved comparison against r11 finds zero coordinate difference in every retained body, limb, shoulder, torso and core component; only the head and its six neck end sections are changed.</p>
<p><strong>1,792 triangles · native Stone Golem 1,200 · 1.493× · cap 1,800.</strong> The head replacement uses 108 triangles rather than the previous 116, saving eight. One mesh/material, four packed 512px maps, original eight bone identities and seven actions remain.</p>
<h2>Previous and corrected head — matched views</h2><div><button data-view="crown-detail">Front head close-up</button><button data-view="crown-side">Left-facing head close-up</button><button data-view="three-quarter">Whole surface</button><button data-view="front">Front surface</button><button data-view="side">True side surface</button><button data-view="front-clay">Front clay</button><button data-view="side-clay">True side clay</button><button data-view="side-reference">Angled side</button></div><div class="pair"><figure><img id="before" src="before/{previous}--crown-detail.png" alt="Previous split head"><figcaption>Previous r11 — incorrect independent halves and loose purple pieces</figcaption></figure><figure><img id="after" src="{ID}--crown-detail.png" alt="Single crystal with recessed fissure"><figcaption>Current r12 — one shell, bevel walls and recessed purple crack floor</figcaption></figure></div>
<h2>Front reference</h2><div class="pair reference"><figure><img src="concept-front.png" alt="Concept front"><figcaption>Adopted concept front</figcaption></figure><figure><img src="{ID}--front-reference.png" alt="Current frontal clay"><figcaption>Current front clay — one continuous head outline</figcaption></figure></div>
<h2>Left-facing side reference</h2><div class="pair reference"><figure><img src="concept-side.png" alt="Concept side"><figcaption>Concept — front/head left, back right</figcaption></figure><figure><img src="{ID}--side-reference-clay.png" alt="Current left-facing clay"><figcaption>Current angled side — closed rear crystal surface</figcaption></figure></div>
<h2>Adopted concept</h2><img src="../../../creature-concepts/2026-10-03/the-rift-titan.png" alt="Full adopted concept sheet">
<p>The saved head contains one connected closed component, 56 shared vertices and 108 triangles: 76 cortex/back/end triangles, 24 bevel triangles and eight recessed purple floor triangles. The floor sits behind the front lips and in front of the rear wall at every cross-section. All 76 existing supports pass rest plus 35 sampled action poses. Closing-face interior/edge checks pass 8,064 arm/digit, 14,112 limb-crystal, 2,016 upper-thorax and 1,512 neck/head samples across 36 poses, with zero measured outside distance.</p>
<p>This corrects the head interpretation; it does not establish final boss or 85% concept-match acceptance. Further fracture detail, core density, crest debris and material placement remain. Native every-frame deformation and live performance remain pending. Adequate boss tally remains 1/6. <a href="../../RIFT-TITAN-REFINEMENT-OUTLOOK.md">Updated outlook</a>.</p>
<p><a href="../../../../../{row['source']}">Editable Blender model</a> · <a href="{ID}.glb">Skinned export</a> · <a href="head-authoring.json">Head correction</a> · <a href="head-verification.json">Connected shell and crack-depth checks</a> · <a href="body-preservation.json">Body compared with r11</a> · <a href="verification.json">Mesh/export checks</a> · <a href="attachment-verification.json">Support checks</a> · <a href="neck-head-face-verification.json">Neck/head closing faces</a> · <a href="side-orientation.json">Camera direction</a> · <a href="provenance.json">Source provenance</a></p>
<script>document.querySelectorAll('button[data-view]').forEach(b=>b.onclick=()=>{{document.getElementById('before').src='before/{previous}--'+b.dataset.view+'.png';document.getElementById('after').src='{ID}--'+b.dataset.view+'.png';}});</script></html>'''
sources=['tools/rift_titan_r4_base.py','tools/rift_titan_wrapped_torso.py','tools/rift_titan_silhouette_fit.py','tools/rift_titan_joint_silhouette.py','tools/rift_titan_crystal_limbs.py','tools/rift_titan_crown_profile.py','tools/rift_titan_layered_weathering.py','tools/rift_titan_notched_stone.py','tools/rift_titan_cracked_head.py','tools/refine-first-bloom.py','tools/refine-rift-titan-cracked-head-r12.py','tools/refine-rift-titan-notched-r11.py','tools/review-rift-titan-cracked-head-r12.py','tools/review-rift-titan-cracked-before-r12.py','tools/verify-rift-titan-cracked-head-r12.py','tools/publish-rift-titan-cracked-head-r12.py',row['source'],detail['source'],'docs/art/creature-concepts/2026-10-03/the-rift-titan.png','docs/art/creature-models/RIFT-TITAN-REFINEMENT-OUTLOOK.md']
(OUT/'provenance.json').write_text(json.dumps(dict(base_commit=subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),hashes={p:hashlib.sha256((ROOT/p).read_bytes()).hexdigest() for p in sources},scope='user correction: one continuous crystal head with a beveled recessed purple fissure; body geometry preserved',acceptance='unaccepted head correction; no 85% or final boss acceptance'),indent=2)+'\n',encoding='utf-8')
(OUT/'gallery.html').write_text(html,encoding='utf-8')
for target in re.findall(r'(?:href|src)="([^"]+)"',html):assert (OUT/target).resolve().is_file(),target
for view in (*views,'crown-detail','crown-side'):assert (OUT/(ID+'--'+view+'.png')).is_file() and (OUT/'before'/(previous+'--'+view+'.png')).is_file()
print('VERIFIED r12 gallery, one closed head, inset purple fissure, matching close-ups, unchanged body and 1792 triangles')
